const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let previewEnabled=localStorage.getItem('atlas-previews')==='true';
let token='',page='Overview',drives=[],offset=0,total=0,items=[],selected=new Set(),folder='',rootDrive='',view='list',timer,renderVersion=0;
const icons={'Overview':'◫','All Files':'▤','Drives':'▣','Projects':'◇',"Memories":'▱','Duplicates':'⧉','Analytics':'▥','Recent Scans':'◷','Updates':'↻','Settings':'⚙'};
const categories=['Photography','Video','Audio','Graphic Design','Documents','Presentations','Spreadsheets','3D Assets','Fonts','Archives','Code / Web','Project Files','Other'];
const bytes=n=>{n=Number(n)||0; if(!n)return '0 B';const i=Math.min(4,Math.floor(Math.log(n)/Math.log(1024)));return (n/1024**i).toLocaleString(undefined,{maximumFractionDigits:i?1:0})+' '+['B','KB','MB','GB','TB'][i]},num=n=>Number(n||0).toLocaleString(),date=n=>n?new Date(n*1000).toLocaleString():'Not scanned';
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',6000)}
let sessionRefresh=null;
async function apiRequest(path,options={}){
 const send=()=>fetch('/api/'+path,{...options,headers:{...(options.headers||{}),'X-Atlas-Token':token}});
 let response=await send();if(response.status===403){let error;try{error=await response.clone().json()}catch{}if(error?.detail==='Session token required'){
  if(!sessionRefresh)sessionRefresh=fetch('/api/session',{cache:'no-store'}).then(r=>r.json()).then(s=>token=s.token).finally(()=>sessionRefresh=null);
  await sessionRefresh;response=await send();
 }}return response;
}
async function api(path,method='GET',body){const label=workLabel(path,method),end=label?beginWork(label):()=>{};try{const response=await apiRequest(path,{method,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.detail||"Could not complete the operation");if(method!=='GET'&&path.startsWith('drives'))drivesUpdated=0;return data}finally{end()}}

async function act(fn){try{return await fn()}catch(e){toast(e.message)}}
function empty(title,description,button=''){return `<div class="empty"><div class="glyph">◈</div><h2>${esc(title)}</h2><p>${esc(description)}</p>${button}</div>`}
async function navigate(name){page=name;offset=0;folder='';rootDrive='';selected.clear();$('#inspector').close();$('#search').value='';await render()}
function nav(){ $('#nav').innerHTML=Object.entries(icons).map(([n,i])=>`<button data-page="${n}" class="${page===n?'active':''}"><span>${i}</span><span class="nav-label">${n}</span></button>`).join('');$('#nav').onclick=e=>{const b=e.target.closest('[data-page]');if(b)act(()=>navigate(b.dataset.page))}}
let drivesUpdated=0,driveRefresh=null;
async function refreshDrives(force=false){if(!force&&drives.length&&Date.now()-drivesUpdated<15000)return;if(driveRefresh)return driveRefresh;driveRefresh=(async()=>{drives=await api('drives');drivesUpdated=Date.now();$('#connection').innerHTML=`<span class="status-dot"></span>${drives.filter(d=>d.connected).length} connected · ${drives.filter(d=>!d.connected).length} offline`})().finally(()=>driveRefresh=null);return driveRefresh}

function driveCard(d){return `<article class="drive-card"><div class="drive-top">${diskIcon()}<span class="badge ${d.connected?'online':''}">${d.connected?'● Connected':'○ Offline'}</span></div><h3>${esc(d.name)}</h3><span class="muted">${esc(d.label||'Unlabeled archive')}</span><p class="path">${esc(d.current_root||d.root)}</p>${technicalDrive(d)}<div class="meta"><span>${num(d.files)} files</span><span>${bytes(d.bytes)} logical</span></div><p><small>Last scan · ${esc(date(d.last_scan))}</small></p><div class="actions"><button data-browse="${d.id}">Browse</button><button class="primary" data-scan="${d.id}" ${!d.connected?'disabled':''}>${d.last_scan?'↻ Update':'▸ Scan'}</button><button data-manifest="${d.id}">Export</button><button data-json-anchor="${d.id}">Catalog JSON</button><button data-edit-drive="${d.id}">Edit</button>${!d.connected?`<button data-reconnect="${d.id}">Reconnect</button>`:''}</div></article>`}
async function render(){const version=++renderVersion,end=beginWork("Loading "+page+'…');try{nav();$('#content').innerHTML="<div class=\"route-loading\"><span class=\"loading-orbit\"></span><strong>Loading "+esc(page)+"…</strong><small>Preparing your local catalog. You can keep browsing.</small><div class=\"route-loading-line\"></div></div>";$('#title').textContent=page;$('#page-actions').innerHTML='';$('#subtitle').textContent=({'Overview':'Every drive. Every file. Always within reach.','All Files':'Explore your library, even when your drives are offline.','Drives':'Physical archives, one connected library.','Projects':"Projects by year, category, and drive.","Memories":"Memories by year and month, occasion and collection.",'Tags':'Find connections beyond folder structures.','Duplicates':"Candidates and verified content matches. Cleanup is available after review and confirmation.",'Analytics':'Understand your archive. All sizes are logical file sizes.','Recent Scans':'Real progress. Persistent checkpoints.','Updates':"Dates, updates, and changes saved locally.",'Settings':'Your data stays on this computer.'})[page];await refreshDrives();if(version!==renderVersion)return;
if(page==='Overview')await renderOverview();
else if(page==='Drives')$('#content').innerHTML=drives.length?`<div class="drive-grid">${drives.map(driveCard).join('')}</div><p class="notice">Each card is an indexed root. Roots can share a volume or physical disk. Unknown hardware identity is never counted as a separate confirmed physical copy.</p>`:empty('No drives registered','Add a connected drive or import a catalog from Settings.','<button class="primary" data-add>+ Add drive</button>');
else if(page==='Projects')await renderProjects();
else if(page==="Memories")await renderPersonal();
else if(page==='All Files'){renderFilters();await loadFiles()}
else if(page==='Recent Scans')await renderScans();
else if(page==='Updates')await renderUpdates();
else if(page==='Duplicates')await renderDuplicates();
else if(page==='Analytics')await renderAnalytics();
else if(page==='Settings')renderSettings();
}finally{end()}}
function distribution(rows){const max=Math.max(1,...rows.map(r=>r.bytes));return rows.length?rows.map(r=>`<div class="distribution">${r.ext?`<button class="label format-link" data-format-search="${esc(r.ext)}">${esc(r.ext.toUpperCase())}</button>`:`<span class="label">${esc(r.category||r.year||'Unknown')}</span>`}<div class="bar"><span style="width:${Math.max(1,r.bytes/max*100)}%"></span></div><small>${bytes(r.bytes)}</small></div>`).join(''):'<p>No indexed content yet.</p>'}
let fileSort='name',fileDirection='asc',fileController=null,fileRequest=0;
function renderFilters(){
 $('#content').innerHTML=`<div class="file-workbench explorer-workbench"><div class="explorer-tools"><button id="explorer-back" title="Back" aria-label="Back">←</button><button id="explorer-up" title="Up" aria-label="Up">↑</button><select id="drive-filter" aria-label="Drive"><option value="">This PC</option>${drives.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</select><div id="crumbs" class="crumbs"></div><select id="view" aria-label="File view"><option value="list">Details</option><option value="compact">Compact</option><option value="grid4">Grid ×4</option><option value="grid8">Grid ×8</option></select><button id="preview-toggle" aria-pressed="${previewEnabled}" title="Thumbnails">▧</button><details class="explorer-more"><summary aria-label="More options">···</summary><div class="explorer-options"><div class="file-filterbar"><label>Type<select id="category-filter"><option value="">All</option>${categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>Tag<input id="tag-filter"></label><label>Project<input id="project-filter"></label><label>Min. MB<input id="min-size" type="number" min="0"></label><label>From<input id="after-filter" type="date"></label><label>To<input id="before-filter" type="date"></label></div><div class="actions"><button id="reset-files">Clear</button><button id="tree-toggle">Tree</button><button id="bulk">Edit selection <span id="selection-count">0</span></button><button id="export-csv">CSV ↓</button><button id="export-json">JSON ↓</button><button data-io-policy>Managed disk I/O</button></div><label>Sort<select id="file-sort-control">${[['name',"Name"],['drive',"Drive"],['location',"Path"],['size',"Size"],['modified',"Date"],['status',"Status"]].map(([key,label])=>`<option value="${key}" ${fileSort===key?'selected':''}>${label}</option>`).join('')}</select></label><button id="file-sort-direction">${fileDirection==='asc'?'↑ ASC':'↓ DESC'}</button></div></details></div><div id="tree" hidden></div><div class="file-context"><span id="file-load-status" role="status">Local catalog · ready</span><span class="explorer-help">Click a folder to browse · Double-click a file to open · ⓘ for details</span></div><div id="search-progress" class="search-progress" hidden role="status"><span></span><p>Searching your local catalog…</p></div><div id="results"></div></div>`;
 $('#view').value=view;$('#drive-filter').value=rootDrive;
 $('#drive-filter').onchange=e=>{rememberFolder();rootDrive=e.target.value;folder='';$('#search').value='';offset=0;act(loadFiles)};
 $('#explorer-back').onclick=()=>{const old=folderHistory.pop();if(!old)return;rootDrive=old.drive;folder=old.folder;$('#search').value=old.q;$('#drive-filter').value=rootDrive;offset=0;act(loadFiles)};
 $('#explorer-up').onclick=()=>{rememberFolder();if(folder)folder=folder.split(/[\\/]/).slice(0,-1).join('\\');else rootDrive='';$('#drive-filter').value=rootDrive;$('#search').value='';offset=0;act(loadFiles)};
 $('#file-sort-control').onchange=e=>{fileSort=e.target.value;offset=0;act(loadFiles)};$('#file-sort-direction').onclick=()=>{fileDirection=fileDirection==='asc'?'desc':'asc';offset=0;act(loadFiles)};
 $('#preview-toggle').onclick=()=>{previewEnabled=!previewEnabled;localStorage.setItem('atlas-previews',String(previewEnabled));$('#preview-toggle').setAttribute('aria-pressed',String(previewEnabled));act(loadFiles)};
 $('.file-filterbar').onchange=()=>{offset=0;act(loadFiles)};
 $('#view').onchange=()=>{view=$('#view').value;if(view.startsWith('grid')&&!previewEnabled){previewEnabled=true;localStorage.setItem('atlas-previews','true');$('#preview-toggle').setAttribute('aria-pressed','true')}act(loadFiles)};
 $('#reset-files').onclick=()=>{for(const id of ['category-filter','tag-filter','project-filter','min-size','after-filter','before-filter'])$('#'+id).value='';$('#search').value='';offset=0;act(loadFiles)};
 $('#bulk').onclick=()=>editMetadata([...selected]);$('#export-csv').onclick=()=>location.href='/api/export?'+params()+'&format=csv';$('#export-json').onclick=()=>location.href='/api/export?'+params()+'&format=json';
 $('#tree-toggle').onclick=()=>act(async()=>{const t=$('#tree');if(!rootDrive)return toast("Choose a drive");t.hidden=!t.hidden;if(!t.hidden){t.innerHTML='';await treeChildren(t,rootDrive,'')}});
}
let folderHistory=[];
function explorerAtComputer(){return !rootDrive&&!$('#search').value&&['drive-filter','category-filter','tag-filter','project-filter','min-size','after-filter','before-filter'].every(id=>!$('#'+id)?.value)}
function rememberFolder(){folderHistory.push({drive:rootDrive,folder,q:$('#search').value});if(folderHistory.length>100)folderHistory.shift()}
function enterFolder(e){selected.clear();rememberFolder();rootDrive=e.drive_id;folder=e.rel;offset=0;$('#search').value='';$('#drive-filter').value=rootDrive;$('#inspector').close();act(loadFiles)}
function rootLocations(){const results=$('#results');results.innerHTML="<div class=\"explorer-root-label\">Drives and saved catalogs</div><div class=\"explorer-locations\">"+drives.map(d=>`<button data-open-root="${esc(d.id)}">${diskIcon()}<strong>${esc(d.name)}</strong><span>${esc(d.technical?.filesystem||"Offline catalog")} · ${num(d.files)} files</span><small>${d.technical?.capacity?bytes(d.technical.free)+" free of "+bytes(d.technical.capacity):bytes(d.bytes)+' indexados'}</small></button>`).join('')+'</div>';results.onclick=e=>{const b=e.target.closest('[data-open-root]');if(b){rememberFolder();rootDrive=b.dataset.openRoot;folder='';$('#drive-filter').value=rootDrive;offset=0;act(loadFiles)}};$('#crumbs').textContent="This PC";$('#file-load-status').textContent=drives.length+" drives · search to look across all of them";$('#explorer-up').disabled=true;$('#explorer-back').disabled=!folderHistory.length}

function params(){const p=new URLSearchParams({q:$('#search').value,offset,limit:100,sort:fileSort,direction:fileDirection});for(const [id,k] of [['drive-filter','drive'],['category-filter','category'],['tag-filter','tag'],['project-filter','project']])if($('#'+id)?.value)p.set(k,$('#'+id).value);if($('#min-size')?.value)p.set('min_size',Number($('#min-size').value)*1024**2);if($('#after-filter')?.value)p.set('after',new Date($('#after-filter').value).getTime()/1000);if($('#before-filter')?.value)p.set('before',new Date($('#before-filter').value).getTime()/1000+86399);if(!$('#search').value)p.set('directories_first','1');if(rootDrive){p.set('drive',rootDrive);if(folder)p.set('parent',folder);else p.set('directory','root')}return p}
function fileHeader(key,label){return `<th scope="col" aria-sort="${fileSort===key?(fileDirection==='asc'?'ascending':'descending'):'none'}"><button data-file-sort="${key}">${label}<span>${fileSort===key?(fileDirection==='asc'?'↑':'↓'):'↕'}</span></button></th>`}
function syncSelection(){const count=$('#selection-count');if(count)count.textContent=num(selected.size);const all=$('#select-page');if(all){const checked=items.filter(e=>selected.has(e.id)).length;all.checked=!!items.length&&checked===items.length;all.indeterminate=checked>0&&checked<items.length}document.querySelectorAll('#results tr[data-id]').forEach(row=>row.classList.toggle('file-selected',selected.has(+row.dataset.id)))}
async function loadFiles(){
 const version=++fileRequest;fileController?.abort();const controller=fileController=new AbortController(),results=$('#results');if(!results)return;if(explorerAtComputer()){rootLocations();return}const endWork=beginWork("Reading the folder and searching the catalog…");
 results.setAttribute('aria-busy','true');const started=performance.now();$('#file-load-status').textContent="Searching…";if($('#search-progress'))$('#search-progress').hidden=false;if(!results.childElementCount)results.innerHTML='<div class="result-skeleton">'+Array.from({length:6},()=>'<div><i></i><span></span><b></b></div>').join('')+'</div>';
 try{
  const response=await fetch('/api/entries?'+params(),{headers:{'X-Atlas-Token':token},signal:controller.signal});const data=await response.json();if(!response.ok)throw Error(data.detail||"Could not load the catalog");
  if(version!==fileRequest||!results.isConnected)return;items=data.items;total=data.total;
  $('#crumbs').innerHTML=rootDrive?`<button data-folder="">${esc(drives.find(d=>d.id===rootDrive)?.name)}</button>`+folder.split(/[\\/]/).filter(Boolean).map((x,i,a)=>`<span>/</span><button data-folder="${esc(a.slice(0,i+1).join('\\'))}">${esc(x)}</button>`).join(''):"<span>GLOBAL CATALOG</span>";
  results.innerHTML=`${searchResultSummary(data,performance.now()-started)}${data.by_drive?.length&&$('#search').value?`<div class="search-summary">${data.by_drive.map(d=>esc(d.name)+': '+num(d.matches)).join(' · ')}</div>`:''}<div class="table-wrap file-table ${view.startsWith('grid')?'grid-view '+view:view==='compact'?'compact':''}"><table><thead><tr><th class="file-check"><input type="checkbox" id="select-page" aria-label="Select page"></th>${fileHeader('name','Name')}${fileHeader('drive','Drive')}${fileHeader('location','Location')}${fileHeader('size','Size')}${fileHeader('modified','Modified')}${fileHeader('status','Status')}</tr></thead><tbody>${items.map(e=>{const path=e.archived_root+(/[\\/]$/.test(e.archived_root)?'':'\\')+e.rel;return `<tr tabindex="0" data-id="${e.id}" ${e.is_dir?`data-directory="${esc(e.rel)}" data-drive="${esc(e.drive_id)}"`:''}><td class="file-check"><input type="checkbox" data-select="${e.id}" ${selected.has(e.id)?'checked':''} aria-label="Select ${esc(e.name)}"></td><td class="name"><div class="file-name-cell">${thumbnailMarkup(e)}<span class="file-kind-icon">${e.is_dir?'▱':'▫'}</span><span class="file-name-text" title="${esc(e.name)}">${esc(e.name)}${e.favorite?' ★':''}<small>${esc(e.is_dir?'DIRECTORY':e.ext?.toUpperCase()||'FILE')}</small></span><button class="file-info" data-file-info="${e.id}" aria-label="Details for ${esc(e.name)}">ⓘ</button></div></td><td class="file-drive">${esc(e.drive_name)}</td><td class="result-path" title="${esc(path)}">${esc(path)}</td><td class="file-size">${e.is_dir?'DIR':bytes(e.size)}</td><td class="file-modified" title="${esc(date(e.mtime))}">${e.mtime?esc(new Date(e.mtime*1000).toLocaleDateString()):'—'}<small>${e.mtime?esc(new Date(e.mtime*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})):''}</small></td><td><span class="badge ${e.connected?'online':''}">${e.connected?'● Connected':'○ Offline'}</span></td></tr>`}).join('')||"<tr><td colspan=\"7\" class=\"file-empty\">No results. Try a different search or filter.</td></tr>"}</tbody></table></div><div class="pagination"><span>${total?num(offset+1):'0'}–${num(offset+items.length)} / ${num(total)} records</span><div class="actions"><button id="prev" ${offset?'':'disabled'}>← Previous</button><button id="next" ${offset+100<total?'':'disabled'}>Next →</button></div></div>`;
  $('#file-load-status').textContent=num(total)+" records · "+({asc:'ASC',desc:'DESC'}[fileDirection])+' · '+fileSort;
  $('#file-sort-control').value=fileSort;$('#file-sort-direction').textContent=fileDirection==='asc'?'↑ ASC':'↓ DESC';
  syncSelection();if(previewEnabled)void hydrateThumbnails(results);
  $('#prev').onclick=()=>{offset=Math.max(0,offset-100);act(loadFiles)};$('#next').onclick=()=>{offset+=100;act(loadFiles)};
  $('#select-page').onchange=e=>{items.forEach(f=>e.target.checked?selected.add(f.id):selected.delete(f.id));results.querySelectorAll('[data-select]').forEach(box=>box.checked=selected.has(+box.dataset.select));syncSelection()};
  results.onclick=e=>{const info=e.target.closest('[data-file-info]');if(info){act(()=>inspect(+info.dataset.fileInfo));return}const sort=e.target.closest('[data-file-sort]');if(sort){const key=sort.dataset.fileSort;fileDirection=fileSort===key?(fileDirection==='asc'?'desc':'asc'):['size','modified'].includes(key)?'desc':'asc';fileSort=key;offset=0;act(loadFiles);return}if(e.target.matches('[data-select]')){e.target.checked?selected.add(+e.target.dataset.select):selected.delete(+e.target.dataset.select);syncSelection();return}if(e.target.closest('.file-check'))return;const row=e.target.closest('[data-id]');if(row){const item=items.find(x=>x.id===+row.dataset.id);if(item?.is_dir)enterFolder(item);else{results.querySelectorAll('.file-current').forEach(x=>x.classList.remove('file-current'));row.classList.add('file-current')}}};
  results.ondblclick=e=>{if(e.target.closest('input,button'))return;const row=e.target.closest('[data-id]');if(row){const item=items.find(x=>x.id===+row.dataset.id);if(item&&!item.is_dir)act(()=>openOriginal(item.id,item.connected))}};
  $('#explorer-up').disabled=!rootDrive;$('#explorer-back').disabled=!folderHistory.length;results.onkeydown=e=>{if(e.key==='Enter'){const row=e.target.closest('[data-id]'),item=items.find(x=>x.id===+row?.dataset.id);if(item){e.preventDefault();if(e.altKey)act(()=>inspect(item.id));else if(item.is_dir)enterFolder(item);else act(()=>openOriginal(item.id,item.connected))}}};
  $('#crumbs').onclick=e=>{const b=e.target.closest('[data-folder]');if(b){folder=b.dataset.folder;offset=0;act(loadFiles)}};
 }catch(e){if(e.name!=='AbortError'&&version===fileRequest){if($('#file-load-status'))$('#file-load-status').textContent="Could not load";throw e}}
 finally{endWork();if(version===fileRequest&&results.isConnected){results.setAttribute('aria-busy','false');if($('#search-progress'))$('#search-progress').hidden=true}}
}
async function treeChildren(container,did,parent){const p=new URLSearchParams({drive:did,limit:250});if(parent)p.set('parent',parent);else p.set('directory','root');const data=await api('entries?'+p);for(const e of data.items.filter(x=>x.is_dir)){const row=document.createElement('div'),b=document.createElement('button'),sub=document.createElement('div');b.className='tree-node';b.textContent='▸ '+e.name;sub.className='tree-child';sub.hidden=true;b.onclick=()=>act(async()=>{folder=e.rel;rootDrive=did;offset=0;await loadFiles();if(sub.hidden&&!sub.childElementCount)await treeChildren(sub,did,e.rel);sub.hidden=!sub.hidden;b.textContent=(sub.hidden?'▸ ':'▾ ')+e.name});row.append(b,sub);container.append(row)}if(data.total>250){const note=document.createElement('p');note.textContent='First 250 entries shown here. Use the paginated file list for all children.';container.append(note)}}
let inspectorRequest=0;
async function inspect(id){const request=++inspectorRequest,ins=$('#inspector');if(!ins.open)ins.showModal();ins.innerHTML="<div class=\"modal-heading\"><h2 id=\"inspector-title\">File inspector</h2><button id=\"close-inspector\" aria-label=\"Close inspector\">×</button></div><div class=\"modal-skeleton\"><i></i><i></i><i></i><p>Loading local metadata…</p></div>";$('#close-inspector').onclick=()=>ins.close();let e;try{e=await api('entries/'+id)}catch(error){if(request===inspectorRequest&&ins.open){ins.querySelector('.modal-skeleton').innerHTML='<p class="error">'+esc(error.message)+'</p>'}throw error}if(request!==inspectorRequest||!ins.open)return;const a=e.annotation;ins.innerHTML=`<div class="modal-heading"><span class="section-label">FILE INSPECTOR</span><button id="close-inspector">×</button></div><h2 id="inspector-title">${esc(e.name)}</h2><span class="badge ${e.drive.connected?'online':''}">${e.drive.connected?'Connected':'Offline catalog'}</span>${thumbnailMarkup({...e,connected:e.drive.connected})}<dl><dt>Archive</dt><dd>${esc(e.drive.name)} · ${esc(e.drive.label)}</dd><dt>Original path</dt><dd id="original-path">${esc(e.original_path)}</dd><dt>Category / format</dt><dd>${esc(e.category)} · ${esc(e.ext||'Folder')}</dd><dt>Logical size</dt><dd>${bytes(e.size)}${e.is_dir?` · descendants ${bytes(e.folder_totals.bytes)} / ${num(e.folder_totals.files)} files`:''}</dd><dt>Modified</dt><dd>${date(e.mtime)}</dd><dt>Created</dt><dd>${date(e.ctime)}</dd><dt>Technical metadata</dt><dd>${esc(e.metadata)}</dd><dt>SHA-256</dt><dd>${esc(e.sha256||'Verification pending')}</dd><dt>Last verified</dt><dd>${date(e.verified)}</dd><dt>Possible related copies</dt><dd>${e.related.length?e.related.map(x=>`${esc(x.name)} · ${esc(x.rel)}`).join('<br>'):'No matching name and size in the catalog'}</dd><dt>Tags / inherited tags</dt><dd>${esc(a.tags||'None')} ${e.inherited.map(x=>esc(x.tags)).join(', ')}</dd><dt>Project / collection / client</dt><dd>${esc([a.project,a.collection,a.client].filter(Boolean).join(' · ')||'None')}</dd><dt>Notes</dt><dd>${esc(a.notes||'—')}</dd><dt>Catalog last scanned</dt><dd>${date(e.drive.last_scan)}</dd></dl><div class="actions"><button id="copy-path">Copy path</button><button id="open-original" ${!e.drive.connected?'disabled':''}>Show in Explorer</button><button id="edit-meta">Edit metadata</button>${e.is_dir?`<button id="use-project-container">Use as a project folder</button>`:''}<button id="inspector-preview">${previewEnabled?"Refresh thumbnail":"Enable thumbnail"}</button><button id="open-default" ${!e.drive.connected?'disabled':''}>Open</button>${!e.is_dir?`<button id="trash-original" ${!e.drive.connected?'disabled':''}>Move to Recycle Bin…</button>`:''}${!e.is_dir?`<button id="hash-full" ${!e.drive.connected?'disabled':''}>Verify SHA-256</button><button id="hash-partial" ${!e.drive.connected?'disabled':''}>Partial fingerprint</button>`:''}</div><p class="notice">Enable thumbnails to generate them while the drive is connected. Saved thumbnails and metadata remain available offline. Hashing reads the entire original file and may take time.</p>`;$('#close-inspector').onclick=()=>ins.close();$('#copy-path').onclick=()=>act(async()=>{await navigator.clipboard.writeText(e.original_path);toast('Path copied')});$('#open-original').onclick=()=>act(()=>api(`entries/${id}/open`,'POST'));$('#edit-meta').onclick=()=>editMetadata([id],a);if($('#use-project-container'))$('#use-project-container').onclick=()=>act(async()=>{await api('projects/'+id+'/container','POST');projectRoot=String(id);await navigate('Projects')});$('#open-default').onclick=()=>act(()=>api(`entries/${id}/open`,'POST',{mode:'open'}));if($('#trash-original'))$('#trash-original').onclick=()=>act(()=>reviewTrash(id));$('#inspector-preview').onclick=()=>act(async()=>{previewEnabled=true;localStorage.setItem('atlas-previews','true');await inspect(id)});if(previewEnabled)void hydrateThumbnails(ins);for(const partial of [false,true]){const b=$(partial?'#hash-partial':'#hash-full');if(b)b.onclick=()=>act(async()=>{b.disabled=true;b.textContent='Reading original…';try{await api(`entries/${id}/hash`,'POST',{partial});await inspect(id);toast('Verification saved')}finally{b.disabled=false}})}}
function editMetadata(ids,a={}){if(!ids.length)return toast('Select one or more files first');const dialog=document.createElement('dialog');dialog.className='lightbox';dialog.innerHTML=`<form><div class="modal-heading"><h2>Edit metadata · ${ids.length} items</h2><button type="button" data-close>×</button></div><p>Values replace these fields for the selected items.</p>${['tags','project','collection','client','notes'].map(k=>`<label>${k}<input name="${k}" value="${esc(a[k]||'')}"></label>`).join('')}<label class="check"><input name="favorite" type="checkbox" ${a.favorite?'checked':''}> Favorite</label><label class="check"><input name="inherit" type="checkbox" ${a.inherit?'checked':''}> Inherit folder tags</label><button class="primary">Save metadata</button></form>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-close]').onclick=()=>{dialog.close();dialog.remove()};dialog.querySelector('form').onsubmit=e=>{e.preventDefault();act(async()=>{const body=Object.fromEntries(new FormData(e.target));body.ids=ids;body.favorite=e.target.favorite.checked?1:0;body.inherit=e.target.inherit.checked?1:0;await api('annotations','POST',body);dialog.close();dialog.remove();toast('Metadata saved');if($('#results'))await loadFiles()})}}
let scanRefreshBusy=false;
async function renderScans(){if(scanRefreshBusy||page!=='Recent Scans')return;scanRefreshBusy=true;try{const scans=await api('scans');if(page!=='Recent Scans')return;$('#page-actions').innerHTML="<div class=\"actions\"><button id=\"refresh-scans\">↻ Refresh</button><button id=\"clear-scans\">Clear finished scans…</button><button id=\"restore-scans\">Restore history</button></div>";$('#refresh-scans').onclick=()=>act(renderScans);$('#clear-scans').onclick=()=>act(async()=>{if(!confirm("Clear completed and canceled scans from history? Drive catalogs, files, and search results will be kept."))return;const r=await api('scans-history/clear','POST',{confirm:true});toast(r.cleared+" scans hidden from history");await renderScansAfter()});$('#restore-scans').onclick=()=>act(async()=>{await api('scans-history/restore','POST');toast("History restored");await renderScansAfter()});$('#content').innerHTML="<p class=\"notice\">Refreshes every 4 seconds. Clearing a card hides it from this history; offline catalogs and scan events are kept. You can restore the history later.</p>"+(scans.length?scans.map(s=>`<article class="scan ${s.status}"><div class="section-head"><h3>${esc(s.drive_name)}</h3><span class="badge">${esc(s.status.replaceAll('_',' '))}</span></div><small>${date(s.started)} · ${Math.round(((s.finished||Date.now()/1000)-s.started))}s elapsed (includes pauses)</small><div class="scan-stats"><span>${num(s.files)} files</span><span>${num(s.folders)} folders</span><span>${bytes(s.bytes)} accounted</span><span>${s.warnings} warnings</span></div>${s.error?`<p class="error">${esc(s.error)}</p>`:''}<div class="actions">${['running','pausing'].includes(s.status)?`<button data-control="pause" data-sid="${s.id}">Pause</button>`:''}${s.status==='paused'?`<button data-control="resume" data-sid="${s.id}">Resume</button>`:''}${['paused','running','pausing'].includes(s.status)?`<button data-control="cancel" data-sid="${s.id}">Cancel</button>`:''}<button data-changes="${s.id}">Changes & warnings</button>${['completed','completed_with_warnings','cancelled'].includes(s.status)?`<button data-hide-scan="${s.id}">Hide from history…</button>`:''}</div></article>`).join(''):empty("No scans in history","Saved catalogs are still available in All Files and global search."));}finally{scanRefreshBusy=false}}
async function renderScansAfter(){scanRefreshBusy=false;await renderScans()}
let duplicateGroups=[];
async function renderDuplicates(){const [fileGroups,folderGroups]=await Promise.all([api('duplicates'),api('duplicates/folders')]);if(page!=='Duplicates')return;duplicateGroups=fileGroups;$('#page-actions').innerHTML="<div class=\"actions\"><button id=\"global-cleanup\" class=\"primary\">Prepare global cleanup…</button><button id=\"last-cleanup\">Latest cleanup plan</button></div>";$('#global-cleanup').onclick=()=>act(()=>startBatchCleanup());$('#last-cleanup').onclick=()=>{const id=localStorage.getItem('atlas-last-cleanup');if(id)act(()=>showBatchCleanup(id));else toast("No global or project cleanup plans yet")};$('#content').innerHTML=renderFolderDuplicates(folderGroups)+`<div class="section-head"><h2>Duplicate files</h2></div><div class="notice">Cleanup verifies full file contents with SHA-256 before suggesting a plan. Identical copies have the same quality; the most recently modified is the suggested keeper. Different versions need a manual review. Confirmed duplicates go to the Recycle Bin. Every drive in the group must be connected, with no scans pending.</div>`+(duplicateGroups.length?duplicateGroups.map((g,index)=>`<article class="scan"><div class="section-head"><h3>${esc(g.name)}</h3><span class="badge">${esc(g.level)}</span></div><p>${g.copies} copies · ${g.physical_copies??"Unknown"} physical drives · ${bytes(g.potential_savings)} in extra copies</p>${g.items.map(e=>`<p><button data-inspect="${e.id}">${esc(e.drive_name)} → ${esc(e.rel)}</button><small> Modificado: ${date(e.mtime)} · Verified: ${date(e.verified)}</small></p>`).join('')}<div class="actions"><button data-cleanup-group="${index}">Verify and plan cleanup…</button></div></article>`).join(''):empty('No duplicate candidates','Scan more archives to compare filenames, sizes and verified hashes.'));$('#content').querySelectorAll('[data-cleanup-group]').forEach(b=>b.onclick=()=>act(async()=>{b.disabled=true;b.textContent="Verifying full files…";try{const plan=await api('duplicates/prepare-cleanup','POST',{ids:duplicateGroups[+b.dataset.cleanupGroup].items.map(e=>e.id)});showCleanupPlan(plan)}finally{b.disabled=false;b.textContent="Verify and plan cleanup…"}}))}
function showCleanupPlan(plan){const dialog=document.createElement('dialog');dialog.className='cleanup-dialog';const recommended=plan.items.find(x=>x.id===plan.recommended_keep_id);dialog.innerHTML=`<form><div class="modal-heading"><h2>Review duplicate cleanup</h2><button type="button" data-dismiss>×</button></div><p>${esc(plan.reason)}</p><p><small>Verification valid until ${date(plan.expires)}. Files are checked again when you confirm.</small></p><div class="cleanup-copies">${plan.items.map(e=>`<label class="cleanup-copy"><input type="radio" name="keeper" value="${e.id}" ${e.id===recommended.id?'checked':''}><div><strong>${esc(e.drive_name)}</strong><span class="cleanup-path">${esc(e.path)}</span><small>${bytes(e.size)} · Modified: ${date(e.mtime)}</small><span class="cleanup-outcome" data-outcome="${e.id}"></span></div></label>`).join('')}</div><p id="cleanup-summary"></p><div class="notice">Marked copies will go to their drives' Recycle Bins, where Windows can restore them. The operation stops if recycling is unavailable. Space is not freed until the Recycle Bin is emptied. A catalog backup and operation log are saved.</div><label class="check"><input type="checkbox" name="confirmed" required> I have checked these paths and want to move the other copies to the Recycle Bin.</label><div class="actions"><button type="button" data-cancel>Cancel</button><button type="submit" class="danger" disabled>Confirm and move to Recycle Bin</button></div><p data-cleanup-status role="status"></p></form>`;document.body.append(dialog);dialog.showModal();const form=dialog.querySelector('form'),submit=form.querySelector('[type=submit]');const update=()=>{const keep=Number(form.elements.keeper.value),discard=plan.items.filter(e=>e.id!==keep);dialog.querySelectorAll('[data-outcome]').forEach(el=>{const kept=+el.dataset.outcome===keep;el.textContent=kept?"✓ KEEP":"→ RECYCLE";el.className='cleanup-outcome '+(kept?'keep':'discard')});dialog.querySelector('#cleanup-summary').textContent=`Keeping 1 file. Moving ${discard.length} copies to the Recycle Bin (${bytes(discard.reduce((n,e)=>n+e.size,0))} logical bytes).`;submit.disabled=!form.elements.confirmed.checked};form.onchange=update;update();const dismiss=()=>{dialog.close();dialog.remove()};dialog.querySelector('[data-dismiss]').onclick=dismiss;dialog.querySelector('[data-cancel]').onclick=dismiss;form.onsubmit=async e=>{e.preventDefault();if(!form.elements.confirmed.checked)return;submit.disabled=true;const status=dialog.querySelector('[data-cleanup-status]');status.textContent="Rechecking and recycling the confirmed copies…";dialog.querySelectorAll('input,button').forEach(el=>el.disabled=true);dialog.oncancel=e=>e.preventDefault();try{const result=await api('duplicates/cleanup','POST',{plan_id:plan.plan_id,keep_id:Number(form.elements.keeper.value),confirm:true});dialog.innerHTML=`<div class="modal-heading"><h2>${result.errors.length?"Cleanup stopped":"Cleanup complete"}</h2><button data-finish>×</button></div><p>${result.recycled.length} copies moved to the Recycle Bin.</p><p>Conservado: <span class="cleanup-path">${esc(result.kept)}</span></p>${result.recycled.map(x=>`<p class="cleanup-path">→ ${esc(x.path)}</p>`).join('')}${result.errors.map(x=>`<p class="error">${esc(x.path)}: ${esc(x.message)}</p>`).join('')}<p class="notice">${esc(result.message)}</p><p><small>Catalog backup: ${esc(result.backup.path)}</small></p><button data-finish class="primary">Close</button>`;dialog.oncancel=null;dialog.querySelectorAll('[data-finish]').forEach(b=>b.onclick=()=>act(async()=>{dismiss();await renderDuplicates();await refreshDrives()}))}catch(error){status.textContent=error.message+" Close this window and prepare a new preview.";dialog.oncancel=null;dialog.querySelector('[data-dismiss]').disabled=false;dialog.querySelector('[data-cancel]').disabled=false}}}
let analyticsDrive='',analyticsCategory='',analyticsRequest=0;
function analyticsFileRows(files,kind='size'){return files.length?files.map(e=>{const d=drives.find(d=>d.id===e.drive_id),online=!!d?.connected;return `<article class="analytics-file">${thumbnailMarkup({...e,connected:online})}<div class="analytics-file-main"><button class="file-title" data-inspect="${e.id}">${esc(e.name)}</button><small class="analytics-location" title="${esc(e.rel)}">${esc(e.drive_name||d?.name)} · ${esc(e.rel)}</small><span class="analytics-measure">${kind==='folder'?"Empty folder":kind==='date'?date(e.mtime)+' · '+bytes(e.size):bytes(e.size)}</span><span class="badge ${online?'online':''}">${online?"Connected":'Offline'}</span><div class="actions"><button data-open-entry="${e.id}" ${!online?'disabled':''}>Open</button><button data-show-entry="${e.id}" ${!online?'disabled':''}>Show folder</button><button data-trash-entry="${e.id}" ${!online?'disabled':''}>Move to Recycle Bin…</button></div></div></article>`}).join(''):"<p>Nothing in this selection.</p>"}
async function renderAnalytics(){const request=++analyticsRequest;const a=await api('analytics?'+new URLSearchParams({drive_id:analyticsDrive,category:analyticsCategory}));if(page!=='Analytics'||request!==analyticsRequest)return;$('#page-actions').innerHTML=`<div class="actions"><button id="analytics-refresh">↻ Refresh</button><button id="analytics-previews">${previewEnabled?'Desactivar':'Activar'} miniaturas</button></div>`;$('#content').innerHTML=`<div class="filters"><select id="analytics-drive"><option value="">All drives</option>${drives.map(d=>`<option value="${d.id}" ${d.id===analyticsDrive?'selected':''}>${esc(d.name)}</option>`).join('')}</select><select id="analytics-category"><option value="">All categories</option>${categories.map(c=>`<option ${c===analyticsCategory?'selected':''}>${esc(c)}</option>`).join('')}</select><span class="muted analytics-total">${num(a.totals.files)} files · ${bytes(a.totals.bytes)} logical</span></div><div class="analytics-grid"><section class="panel"><h2>Space by category</h2>${distribution(a.categories)}</section><section class="panel"><h2>By modification year</h2>${distribution(a.years)}</section><section class="panel"><h2>Largest files</h2><div class="analytics-list">${analyticsFileRows(a.largest)}</div></section><section class="panel"><h2>Recently modified</h2><div class="analytics-list">${analyticsFileRows(a.recent,'date')}</div></section><section class="panel"><h2>Oldest files</h2><div class="analytics-list">${analyticsFileRows(a.oldest,'date')}</div></section><section class="panel"><h2>Empty folders</h2><div class="analytics-list">${analyticsFileRows(a.empty_folders,'folder')}</div></section><section class="panel"><h2>File formats</h2>${distribution(a.types)}</section><section class="panel"><h2>Catalog drives</h2>${drives.filter(d=>!analyticsDrive||d.id===analyticsDrive).map(d=>`<div class="analytics-file"><div class="analytics-file-main"><strong>${esc(d.name)}</strong><p class="cleanup-path">${esc(d.label||'')} · ${esc(d.root)}</p><span class="badge ${d.connected?'online':''}">${d.connected?"Connected":'Offline'}</span><p>${num(d.files)} files · ${bytes(d.bytes)} logical</p><button data-browse="${d.id}">Browse catalog</button></div></div>`).join('')}<p class="notice">Drive totals cover each full catalog. Opening or recycling needs a connected drive. Recycling requires confirmation. Only empty folders can be removed here.</p></section></div>`;$('#analytics-drive').onchange=()=>{analyticsDrive=$('#analytics-drive').value;act(renderAnalytics)};$('#analytics-category').onchange=()=>{analyticsCategory=$('#analytics-category').value;act(renderAnalytics)};$('#analytics-refresh').onclick=()=>act(async()=>{await refreshDrives();await renderAnalytics()});$('#analytics-previews').onclick=()=>act(async()=>{previewEnabled=!previewEnabled;localStorage.setItem('atlas-previews',String(previewEnabled));await renderAnalytics()});if(previewEnabled)void hydrateThumbnails($('#content'))}
function renderSettings(){$('#content').innerHTML=`<div class="split"><section class="panel"><h2>Portable archive</h2><p>Import a DISK ATLAS SQLite manifest or backup. Repeated imports preserve existing records and personal metadata. Conflicting drive identities are rejected.</p><label>Import catalog<input type="file" id="import-file" accept=".sqlite3,.db,.sqlite"></label><button id="import-button">Import catalog</button><p id="import-status"></p></section><section class="panel"><h2>Database backup</h2><p>Create a consistent SQLite snapshot while the application is running. Keep a copy on a separate disk.</p><button id="backup">Create backup</button><div id="backup-result"></div><p class="notice">For exact rollback: stop DISK ATLAS, preserve your current data folder, then replace data/atlas.sqlite3 with a backup. Remove atlas.sqlite3-wal and atlas.sqlite3-shm only while stopped. Import merges a backup without removing current records.</p></section></div><div class="panel" style="margin-top:20px"><h2>Local by design</h2><p>127.0.0.1:8765 · SQLite schema v1 · Local catalog. No AI, accounts, or external services.</p><p>Use STOP.bat to stop safely. Scan checkpoints persist. Logs, manifests, configuration and backups live in the project's data folder.</p><p class="notice">Optional image and video thumbnails are saved locally and available offline. Video thumbnails require FFmpeg. ffprobe/ExifTool enrichment, rename inference, and automatic batch hashing are not implemented yet. Search supports partial terms, quoted phrases, *.extension and explicit filters; natural-language filter parsing is not implemented. FTS5 is maintained for future indexed query syntax.</p></div>`;$('#backup').onclick=()=>act(async()=>{const r=await api('backup','POST');$('#backup-result').innerHTML=`<a class="download" href="/api/download/backups/${encodeURIComponent(r.name)}">Download ${esc(r.name)} ↓</a>`;toast('Consistent backup created')});$('#import-button').onclick=()=>act(async()=>{const f=$('#import-file').files[0];if(!f)return toast('Choose a catalog file first');$('#import-status').textContent='Importing…';const r=await apiRequest('import',{method:'POST',body:f});const data=await r.json();if(!r.ok)throw Error(data.detail);$('#import-status').textContent=data.policy;await refreshDrives();toast('Catalog imported')})}
async function addDrive(){ $('#modal').showModal();const vs=await api('volumes');$('#volume').innerHTML='<option value="">Choose a detected volume</option>'+vs.map(v=>`<option value="${esc(v.root)}">${esc(v.root)} ${esc(v.label)} · ${esc(v.filesystem)} · ${bytes(v.capacity)} total / ${bytes(v.free)} free</option>`).join('');$('#volume').onchange=()=>{$('#drive-form').elements.root.value=$('#volume').value;const v=vs.find(v=>v.root===$('#volume').value);if(v)$('#drive-form').elements.name.value=v.label}}
$('#add').onclick=()=>act(addDrive);$('#close-modal').onclick=()=>$('#modal').close();$('#drive-form').onsubmit=e=>{e.preventDefault();act(async()=>{const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const d=await api('drives','POST',Object.fromEntries(new FormData(e.target)));$('#modal').close();e.target.reset();await api(`drives/${d.id}/scan`,'POST');await navigate('Recent Scans');toast('Scan started')}finally{button.disabled=false}})};
$('#content').addEventListener('click',e=>act(async()=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-add'))await addDrive();if(b.dataset.pageLink)await navigate(b.dataset.pageLink);if(b.dataset.browse){await navigate('All Files');rootDrive=b.dataset.browse;$('#drive-filter').value=rootDrive;await loadFiles()}if(b.dataset.scan){await api(`drives/${b.dataset.scan}/scan`,'POST');await navigate('Recent Scans')}if(b.dataset.manifest){const r=await api(`drives/${b.dataset.manifest}/manifest`,'POST');location.href='/api/download/manifests/'+encodeURIComponent(r.name)}if(b.dataset.inspect)await inspect(+b.dataset.inspect);if(b.dataset.control){await api(`scans/${b.dataset.sid}/${b.dataset.control}`,'POST');await renderScans()}if(b.dataset.changes)await showScanChanges(b.dataset.changes);if(b.dataset.editDrive)await editDriveModal(b.dataset.editDrive);if(b.dataset.reconnect){const d=drives.find(x=>x.id===b.dataset.reconnect);const root=prompt('New root path. Confirm this is the same archive: '+d.name,d.root);if(!root)return;if(!confirm('Associate this location with '+d.name+'? Verify the physical label before continuing.'))return;await api(`drives/${d.id}/reconnect`,'POST',{root,confirm:true});await render()}}));
let searchTimer;$('#search').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>act(async()=>{if(page!=='All Files'){page='All Files';renderVersion++;nav();$('#title').textContent='All Files';$('#subtitle').textContent="Search across all catalogs, including disconnected drives.";$('#page-actions').innerHTML='';$('#inspector').close();renderFilters()}for(const id of ['drive-filter','category-filter','tag-filter','project-filter','min-size','after-filter','before-filter'])if($('#'+id))$('#'+id).value='';rootDrive='';folder='';offset=0;await loadFiles()}),220)};
$('#theme').onclick=()=>{document.body.classList.toggle('light');localStorage.setItem('atlas-theme',document.body.classList.contains('light')?'light':'dark')};if(localStorage.getItem('atlas-theme')==='light')document.body.classList.add('light');document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}});
act(async()=>{token=(await api('session')).token;await render()});setInterval(()=>void pollActivity(),3000);

$('#content').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.openEntry)act(()=>api('entries/'+b.dataset.openEntry+'/open','POST',{mode:'open'}));if(b.dataset.showEntry)act(()=>api('entries/'+b.dataset.showEntry+'/open','POST'));if(b.dataset.trashEntry)act(()=>reviewTrash(+b.dataset.trashEntry));if(b.dataset.hideScan)act(async()=>{if(!confirm("Hide this scan from history? Its catalog will remain available."))return;await api('scans-history/clear','POST',{ids:[b.dataset.hideScan],confirm:true});await renderScans()})});

const mediaExts=new Set('jpg jpeg png tif tiff webp bmp gif heic heif avif psd mov mp4 mxf avi mkv webm m4v mpg mpeg'.split(' '));
function thumbnailMarkup(e,force=false){if((!previewEnabled&&!force)||e.is_dir||!mediaExts.has(e.ext))return '';return `<span class="media-thumb" data-thumbnail="${e.id}" data-connected="${e.connected?'1':'0'}" data-version="${e.mtime||0}" title="Local thumbnail"><span class="thumb-placeholder">${['Video'].includes(e.category)?'▶':'▧'}</span><img loading="lazy" alt="Thumbnail for ${esc(e.name)}" hidden></span>`}
const thumbnailObservers=new WeakMap(),thumbnailJobs=new Map();let thumbnailRunning=0;const thumbnailQueue=[];
function drainThumbnails(){while(thumbnailRunning<2&&thumbnailQueue.length){const job=thumbnailQueue.shift();if(!job.el.isConnected){thumbnailJobs.delete(job.id);job.resolve(null);continue}thumbnailRunning++;api('entries/'+job.id+'/thumbnail','POST').then(job.resolve,job.reject).finally(()=>{thumbnailRunning--;thumbnailJobs.delete(job.id);drainThumbnails()})}}
function queueThumbnail(el){const id=el.dataset.thumbnail;if(thumbnailJobs.has(id)){const queued=thumbnailQueue.find(job=>job.id===id);if(queued)queued.el=el;return thumbnailJobs.get(id);}const promise=new Promise((resolve,reject)=>thumbnailQueue.push({id,el,resolve,reject}));thumbnailJobs.set(id,promise);drainThumbnails();return promise}
async function hydrateThumbnails(container,enabled=previewEnabled){
 if(!container)return;thumbnailObservers.get(container)?.disconnect();
 const load=el=>{if(!el.isConnected||!enabled)return;const img=el.querySelector('img'),url='/api/entries/'+el.dataset.thumbnail+'/thumbnail?v='+encodeURIComponent(el.dataset.version);img.loading='eager';img.decoding='async';
  const display=()=>{if(el.isConnected){img.hidden=false;el.querySelector('.thumb-placeholder')?.remove();el.title="Local thumbnail · available offline"}};
  img.onload=display;img.onerror=async()=>{img.onerror=null;if(el.dataset.connected!=='1'){el.title="No saved thumbnail. Connect the drive to generate one.";return}try{el.classList.add('thumb-loading');const result=await queueThumbnail(el);if(result&&el.isConnected&&enabled){img.onerror=()=>{el.title="Thumbnail unavailable"};img.src=result.url+'?v='+encodeURIComponent(el.dataset.version)}}catch(error){el.title=error.message;el.classList.add('thumb-unavailable')}finally{el.classList.remove('thumb-loading')}};img.src=url;
 };
 if(!('IntersectionObserver' in window)){container.querySelectorAll('[data-thumbnail]').forEach(load);return}
 const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){observer.unobserve(entry.target);load(entry.target)}},{rootMargin:'180px'});thumbnailObservers.set(container,observer);container.querySelectorAll('[data-thumbnail]').forEach(el=>observer.observe(el));
}
async function reviewTrash(id){const plan=await api('entries/'+id+'/prepare-trash','POST');const dialog=document.createElement('dialog');dialog.innerHTML=`<form><div class="modal-heading"><h2>Enviar ${plan.is_dir?"empty folder":"file"} to the Recycle Bin</h2><button type="button" data-dismiss>×</button></div><p><strong>${esc(plan.drive_name)}</strong></p><p class="cleanup-path">${esc(plan.path)}</p><p>${bytes(plan.size)} · ${plan.is_dir?"Verified empty folder":"Original file"}</p><p class="notice">Windows will move it to this drive's Recycle Bin, where it can be restored. A catalog backup is saved. Projects that reference this path may need relinking. There is no fallback to permanent deletion.</p><label class="check"><input type="checkbox" name="confirmed" required> I have checked this path and want to move it to the Recycle Bin.</label><div class="actions"><button type="button" data-dismiss>Cancel</button><button class="danger" type="submit" disabled>Confirm and move to Recycle Bin</button></div><p data-status role="status"></p></form>`;document.body.append(dialog);dialog.showModal();const form=dialog.querySelector('form'),submit=form.querySelector('[type=submit]'),close=()=>{dialog.close();dialog.remove()};dialog.querySelectorAll('[data-dismiss]').forEach(b=>b.onclick=close);form.onchange=()=>submit.disabled=!form.elements.confirmed.checked;form.onsubmit=async event=>{event.preventDefault();if(!form.elements.confirmed.checked)return;dialog.querySelectorAll('input,button').forEach(x=>x.disabled=true);dialog.oncancel=e=>e.preventDefault();dialog.querySelector('[data-status]').textContent="Verifying and moving to the Recycle Bin…";try{const result=await api('trash','POST',{plan_id:plan.plan_id,confirm:true});close();$('#inspector').close();toast(result.message);await refreshDrives();if(page==='Analytics')await renderAnalytics();else if($('#results'))await loadFiles()}catch(error){dialog.oncancel=null;dialog.querySelector('[data-status]').textContent=error.message;dialog.querySelectorAll('[data-dismiss]').forEach(b=>b.disabled=false)}}}

function renderFolderDuplicates(groups){return `<div class="section-head"><h2>Duplicate folders · priority</h2><span class="badge">${groups.length} groups</span></div><p class="notice">Same name: a candidate. Matching inventory: the same relative names, structure, and sizes, but contents may differ. Matching hashes: full SHA-256 values are saved for every file. Comparison works offline. Folders with contents cannot be removed from this view.</p>`+(groups.length?groups.map(g=>`<article class="scan folder-duplicate"><div class="section-head"><h3>▱ ${esc(g.name)}</h3><span class="badge">${g.level==='verified hashes'?"Matching full hashes":g.level==='matching inventory'?"Matching inventory":"Matching name"}</span></div><p>${g.copies} folders · up to ${bytes(g.bytes)} each${g.potential_savings!==null?' · '+bytes(g.potential_savings)+" in candidate copies":''}</p>${g.items.map(e=>`<div class="folder-copy"><div><button data-folder-browse="${e.id}">${esc(e.drive_name)} → ${esc(e.rel)}</button><small>${num(e.files)} files · ${num(e.folders)} subfolders · ${bytes(e.bytes)}</small></div><div class="actions"><button data-inspect="${e.id}">Details</button><button data-clean-project="${e.id}">Clean up inside this folder…</button></div></div>`).join('')}${g.truncated?"<small>Showing the group's first 20 locations.</small>":''}</article>`).join(''):empty("No candidate folders","Compares saved inventories across all drives, even when disconnected."))}
let projectRoot='all',projectQuery='',projectOffset=0,personalRoot='all',personalQuery='',personalOffset=0;
function rootOptions(roots,chosen){return "<option value=\"\">Choose a parent folder…</option>"+roots.map(r=>`<option value="${esc(r.key)}" ${r.key===chosen?'selected':''}>${esc(r.label)}</option>`).join('')}
function indexActions(e){const d=drives.find(d=>d.id===e.drive_id),online=!!d?.connected;return `<span class="badge ${online?'online':''}">${online?"Connected":'Offline'}</span><div class="actions"><button data-folder-browse="${e.id}">${e.is_dir?'Explorar':"View archive"}</button><button data-show-entry="${e.id}" ${online?'':'disabled'}>Show folder</button>${e.is_dir?`<button data-clean-project="${e.id}">Clean up project duplicates…</button>`:''}</div>`}
async function renderProjects(){await renderLibrary('projects')}
async function renderPersonal(){await renderLibrary('personal')}
const libraryStates=Object.fromEntries(['projects','personal'].map(kind=>[kind,{q:'',offset:0,groups:[],total:0,selected:null,location:null,path:'',fileQuery:'',fileOffset:0,view:'grid4',previews:true,request:0,files:[],fileTotal:0,contentRequest:0}]));
const libraryPage=kind=>kind==='projects'?'Projects':"Memories";
async function renderLibrary(kind,fetchGroups=true){const state=libraryStates[kind],version=++state.request;
 if(fetchGroups){const data=await api('library?'+new URLSearchParams({kind,q:state.q,offset:state.offset}));if(page!==libraryPage(kind)||version!==state.request)return;state.groups=data.items;state.total=data.total;state.analysisStatus=data.analysis_status;state.coverage=data.coverage;if(state.selected&&!state.groups.some(g=>g.key===state.selected.key)){state.selected=null;state.location=null}}
 if(page!==libraryPage(kind))return;const old=$('#library-search'),focus=old===document.activeElement,caret=old?.selectionStart;if(focus&&old.value!==state.q)return;
 $('#content').innerHTML=`<div class="library-explorer" data-library-kind="${kind}"><div class="library-tools"><button id="library-back" ${state.selected?'':'hidden'} title="Back to catalog">←</button><input id="library-search" value="${esc(state.q)}" placeholder="${kind==='projects'?"Find a project across all drives…":"Find an occasion or collection…"}" aria-label="Search library"><span>${state.analysisStatus==='analyzing'?"Analyzing… · ":''}${state.coverage&&state.coverage.indexed_drives<state.coverage.registered_drives?"Drives awaiting a scan · ":''}${num(state.total)} ${kind==='projects'?(state.total===1?'proyecto':'proyectos'):(state.total===1?'recuerdo':'recuerdos')}</span><select id="library-view" aria-label="Vista of biblioteca"><option value="grid4">Grid ×4</option><option value="grid8">Grid ×8</option><option value="list">Details</option><option value="compact">Compact</option></select><button id="library-previews" aria-pressed="${state.previews}" title="Toggle thumbnails">▧</button></div><div id="library-main"></div></div>`;
 $('#library-view').value=state.view;if(focus){$('#library-search').focus();$('#library-search').setSelectionRange(caret,caret)}let debounce;
 $('#library-search').oninput=e=>{clearTimeout(debounce);const value=e.target.value;debounce=setTimeout(()=>{state.q=value;state.offset=0;act(()=>renderLibrary(kind))},260)};
 $('#library-back').onclick=()=>{state.selected=null;state.location=null;act(()=>renderLibrary(kind,false))};$('#library-view').onchange=e=>{state.view=e.target.value;act(()=>renderLibrary(kind,false))};$('#library-previews').onclick=()=>{state.previews=!state.previews;act(()=>renderLibrary(kind,false))};
 if(state.selected)await drawLibrarySplit(kind);else drawLibraryGallery(kind);
 if(state.analysisStatus==='analyzing')setTimeout(()=>{if(page===libraryPage(kind)&&!state.selected)act(()=>renderLibrary(kind))},2500);
}
function libraryAlert(g){const a=g.duplicate_analysis;if(!a)return '';const text=a.level==='critical'?"⚠ Verified exact copy · "+bytes(a.verified_savings):a.level==='inventory'?"Repeated inventory · up to "+bytes(a.potential_savings):a.level==='name'?"Repeated name · compare contents":'';return text?`<span class="library-alert ${a.level}" title="Comparison of saved catalogs. Savings from overlapping projects are not added together. Nothing is removed automatically.">${esc(text)}</span>`:''}
function libraryCoverMarkup(location,enabled){return `<span class="library-cover" ${enabled&&location.is_dir?`data-library-cover="${location.id}" data-cover-drive="${esc(location.drive_id)}"`:''}>${location.is_dir?'<span class="library-folder-icon">▱</span>':thumbnailMarkup({...location,connected:!!drives.find(d=>d.id===location.drive_id)?.connected},enabled)||'<span class="library-folder-icon">▫</span>'}</span>`}
function drawLibraryGallery(kind){const s=libraryStates[kind],main=$('#library-main');main.className='library-catalog '+s.view;
 main.innerHTML=`<div class="library-group-grid">${s.groups.map(g=>{const location=g.locations.find(e=>drives.find(d=>d.id===e.drive_id)?.connected)||g.locations[0];return `<article class="library-group"><button data-library-group="${g.key}" class="library-group-open" title="Open ${esc(g.name)} and its ${g.location_count} locations">${libraryCoverMarkup(location,s.previews)}${libraryAlert(g)}<span class="library-group-name">${esc(g.name)}</span><small>${num(g.drive_count)} ${g.drive_count===1?'disco':'discos'} · ${num(g.location_count)} ${g.location_count===1?"location":"locations"}</small><span class="library-disks">${esc([...new Set(g.locations.map(e=>e.drive_name))].join(' · '))}</span></button></article>`}).join('')||empty("No matches","Projects and memories from your catalogs come together here, even offline.")} </div><div class="library-pagination"><span>${num(s.offset+s.groups.length)} / ${num(s.total)}</span><button data-library-page="prev" ${s.offset?'':'disabled'}>←</button><button data-library-page="next" ${s.offset+100<s.total?'':'disabled'}>→</button></div>`;
 main.onclick=e=>{const group=e.target.closest('[data-library-group]');if(group){const selected=s.groups.find(g=>g.key===group.dataset.libraryGroup);s.selected=selected;s.location=selected.locations.find(l=>drives.find(d=>d.id===l.drive_id)?.connected)||selected.locations[0];s.path=s.location.rel;s.fileOffset=0;s.fileQuery='';act(()=>renderLibrary(kind,false));return}const pager=e.target.closest('[data-library-page]');if(pager){s.offset=pager.dataset.libraryPage==='prev'?Math.max(0,s.offset-100):s.offset+100;act(()=>renderLibrary(kind))}};
 if(s.previews)hydrateLibraryCovers(main);
}
async function drawLibrarySplit(kind){const s=libraryStates[kind],g=s.selected,main=$('#library-main');main.className='library-split';main.onclick=null;
 main.innerHTML=`<aside class="library-locations"><div class="library-selected-name"><strong>${esc(g.name)}</strong>${libraryAlert(g)}<small>${num(g.location_count)} locations en ${num(g.drive_count)} discos</small></div><div class="library-location-list">${g.locations.map(l=>{const online=!!drives.find(d=>d.id===l.drive_id)?.connected;return `<div class="library-location ${s.location.id===l.id?'active':''}"><button data-library-location="${l.id}"><span class="library-location-drive">${diskIcon()} ${esc(l.drive_name)} <small>${online?'●':'○'}</small></span><span class="library-location-path">${esc(l.path)}</span><small>${num(l.files)} files · ${bytes(l.bytes)}</small></button><div class="library-location-actions"><button data-copy-library-path="${l.id}" title="Copy path">Copy path</button><button data-reveal-library="${l.id}" ${online?'':'disabled'} title="Show in Explorer">↗</button></div></div>`}).join('')}</div><details class="library-switch"><summary>${kind==='projects'?"Other projects":"Other memories"}</summary>${s.groups.filter(x=>x.key!==g.key).map(x=>`<button data-switch-library="${x.key}">${esc(x.name)} <small>${x.location_count}</small></button>`).join('')}</details></aside><section class="library-inside"><div class="library-inside-tools"><button id="library-up" ${s.path===s.location.rel?'disabled':''} title="Up">↑</button><div id="library-crumbs" class="crumbs"></div><input id="library-file-search" value="${esc(s.fileQuery)}" placeholder="Search within…" aria-label="Search this location"></div><div id="library-files" class="library-files ${s.view}" aria-live="polite"><div class="route-loading"><span class="loading-orbit"></span><small>Loading contents…</small></div></div></section>`;
 main.querySelectorAll('[data-library-location]').forEach(button=>button.onclick=()=>{s.location=g.locations.find(l=>l.id===+button.dataset.libraryLocation);s.path=s.location.rel;s.fileOffset=0;s.fileQuery='';act(()=>drawLibrarySplit(kind))});
 main.querySelectorAll('[data-copy-library-path]').forEach(button=>button.onclick=()=>act(async()=>{const l=g.locations.find(x=>x.id===+button.dataset.copyLibraryPath);await navigator.clipboard.writeText(l.path);toast("Path copied")}));main.querySelectorAll('[data-reveal-library]').forEach(button=>button.onclick=()=>act(()=>api('entries/'+button.dataset.revealLibrary+'/open','POST')));
 main.querySelectorAll('[data-switch-library]').forEach(button=>button.onclick=()=>{s.selected=s.groups.find(x=>x.key===button.dataset.switchLibrary);s.location=s.selected.locations.find(l=>drives.find(d=>d.id===l.drive_id)?.connected)||s.selected.locations[0];s.path=s.location.rel;s.fileOffset=0;s.fileQuery='';act(()=>drawLibrarySplit(kind))});
 $('#library-up').onclick=()=>{if(s.path===s.location.rel)return;s.path=s.path.split(/[\\/]/).slice(0,-1).join('\\');s.fileOffset=0;s.fileQuery='';act(()=>drawLibrarySplit(kind))};let debounce;$('#library-file-search').oninput=e=>{clearTimeout(debounce);s.fileQuery=e.target.value;debounce=setTimeout(()=>{s.fileOffset=0;act(()=>loadLibraryFiles(kind))},250)};
 await loadLibraryFiles(kind);
}
async function loadLibraryFiles(kind){const s=libraryStates[kind],request=++s.contentRequest,box=$('#library-files'),location=s.location;if(!box||!location)return;box.setAttribute('aria-busy','true');const p=new URLSearchParams({drive:location.drive_id,offset:s.fileOffset,limit:100,sort:'name',direction:'asc',directories_first:1});if(s.fileQuery){p.set('folder',s.path);p.set('q',s.fileQuery)}else p.set('parent',s.path);
 try{const data=location.is_dir?await api('entries?'+p):{items:[{...location,connected:!!drives.find(d=>d.id===location.drive_id)?.connected}],total:1};if(page!==libraryPage(kind)||request!==s.contentRequest||!box.isConnected)return;s.files=data.items;s.fileTotal=data.total;const relative=s.path===location.rel?[]:s.path.slice(location.rel.length+1).split(/[\\/]/);$('#library-crumbs').innerHTML=`<button data-library-path="${esc(location.rel)}">${esc(s.selected.name)}</button>`+relative.map((part,i)=>`<span>/</span><button data-library-path="${esc(location.rel+'\\'+relative.slice(0,i+1).join('\\'))}">${esc(part)}</button>`).join('');$('#library-crumbs').onclick=e=>{const b=e.target.closest('[data-library-path]');if(b){s.path=b.dataset.libraryPath;s.fileQuery='';s.fileOffset=0;act(()=>drawLibrarySplit(kind))}};
 box.innerHTML=`<div class="library-file-grid">${data.items.map(e=>`<article class="library-file" data-library-item="${e.id}"><button class="library-file-main" data-enter-library="${e.id}">${libraryCoverMarkup(e,s.previews)}<strong title="${esc(e.name)}">${esc(e.name)}</strong><small>${e.is_dir?'Carpeta':bytes(e.size)+' · '+esc(e.ext.toUpperCase())}</small></button><button class="library-file-info" data-library-info="${e.id}" aria-label="Details for ${esc(e.name)}">ⓘ</button></article>`).join('')||"<p class=\"library-empty\">No files in this selection.</p>"}</div><div class="library-pagination"><span>${num(data.total)} items · ${esc(location.drive_name)}</span><button data-files-page="prev" ${s.fileOffset?'':'disabled'}>←</button><button data-files-page="next" ${s.fileOffset+100<data.total?'':'disabled'}>→</button></div>`;
 const enter=e=>{if(e.is_dir){s.path=e.rel;s.fileOffset=0;s.fileQuery='';act(()=>drawLibrarySplit(kind))}else{box.querySelectorAll('.selected').forEach(x=>x.classList.remove('selected'));box.querySelector('[data-library-item="'+e.id+'"]').classList.add('selected')}};
 box.onclick=event=>{const info=event.target.closest('[data-library-info]');if(info)return act(()=>inspect(+info.dataset.libraryInfo));const button=event.target.closest('[data-enter-library]');if(button)return enter(s.files.find(e=>e.id===+button.dataset.enterLibrary));const pager=event.target.closest('[data-files-page]');if(pager){s.fileOffset=pager.dataset.filesPage==='prev'?Math.max(0,s.fileOffset-100):s.fileOffset+100;act(()=>loadLibraryFiles(kind))}};
 box.ondblclick=event=>{const button=event.target.closest('[data-enter-library]'),entry=s.files.find(e=>e.id===+button?.dataset.enterLibrary);if(entry&&!entry.is_dir)act(()=>openOriginal(entry.id,entry.connected))};box.onkeydown=event=>{if(event.key!=='Enter')return;const button=event.target.closest('[data-enter-library]'),entry=s.files.find(e=>e.id===+button?.dataset.enterLibrary);if(entry&&!entry.is_dir){event.preventDefault();act(()=>openOriginal(entry.id,entry.connected))}};
 if(s.previews){hydrateLibraryCovers(box);void hydrateThumbnails(box,true)}
 }finally{if(box.isConnected&&request===s.contentRequest)box.setAttribute('aria-busy','false')}
}
let coverActive=0;const coverQueue=[],coverObservers=new WeakMap();
function drainLibraryCovers(){while(coverActive<3&&coverQueue.length){const el=coverQueue.shift();if(!el.isConnected)continue;coverActive++;api('entries/'+el.dataset.libraryCover+'/cover').then(result=>{if(!el.isConnected||!result.entry)return;const e=result.entry;e.connected=!!drives.find(d=>d.id===e.drive_id)?.connected;el.innerHTML=thumbnailMarkup(e,true);void hydrateThumbnails(el,true)}).catch(error=>{el.title=error.message}).finally(()=>{coverActive--;drainLibraryCovers()})}}
function hydrateLibraryCovers(container){coverObservers.get(container)?.disconnect();const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){observer.unobserve(entry.target);coverQueue.push(entry.target)}drainLibraryCovers()},{rootMargin:'120px'});coverObservers.set(container,observer);container.querySelectorAll('[data-library-cover]').forEach(el=>observer.observe(el))}
$('#content').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.folderBrowse)act(async()=>{const entry=await api('entries/'+b.dataset.folderBrowse+'/location');if(!entry.is_dir)return inspect(entry.id);await navigate('All Files');rootDrive=entry.drive_id;folder=entry.rel;$('#drive-filter').value=rootDrive;offset=0;await loadFiles()});if(b.dataset.editProject)act(async()=>{const year=prompt("Project year (leave blank to estimate)",b.dataset.year||'');if(year===null)return;const category=prompt("Project category (e.g. Food / Video)",b.dataset.category||'');if(category===null)return;await api('projects/'+b.dataset.editProject+'/profile','POST',{year,category});await renderProjects()});if(b.dataset.personalCollection)act(async()=>{await api('projects/'+b.dataset.personalCollection+'/container','POST');personalRoot=b.dataset.personalCollection;personalOffset=0;await renderPersonal()})});

$('#content').addEventListener('click',event=>{const button=event.target.closest('[data-clean-project]');if(button)act(()=>startBatchCleanup(+button.dataset.cleanProject))});
async function startBatchCleanup(scopeId=null){const result=await api('cleanup-batches','POST',{scope_id:scopeId});localStorage.setItem('atlas-last-cleanup',result.id);await showBatchCleanup(result.id)}
async function showBatchCleanup(id){const dialog=document.createElement('dialog');dialog.className='cleanup-dialog batch-dialog';dialog.innerHTML="<div class=\"modal-heading\"><h2>Cleanup plan</h2><button data-close-batch>×</button></div><div data-batch-body>Loading…</div>";document.body.append(dialog);dialog.showModal();let pageOffset=0,polling=false,pollTimer,reviewConfirmed=false;const close=()=>{clearInterval(pollTimer);dialog.close();dialog.remove()};dialog.querySelector('[data-close-batch]').onclick=close;dialog.addEventListener('cancel',()=>clearInterval(pollTimer));const poll=async()=>{if(polling||!dialog.isConnected)return;polling=true;try{const job=await api('cleanup-batches/'+id+'?offset='+pageOffset);if(!dialog.isConnected)return;const ready=job.status==='ready',busy=['analyzing','cleaning'].includes(job.status),review=job.items||[];dialog.querySelector('[data-batch-body]').innerHTML=`<p><strong>${esc(job.scope_name)}</strong> · <span class="badge">${esc({analyzing:"Analyzing originals",ready:"Ready to review",cleaning:"Moving to the Recycle Bin",completed:"Completed",stopped:"Stopped",cancelled:"Canceled",failed:"Analysis failed"}[job.status]||job.status)}</span></p><div class="notice">Same-size files are compared using full SHA-256 hashes, even when names differ. The most recently modified copy is kept; equal dates are resolved by path order. Project cleanup stays within the selected folder. Offline drives and inaccessible files are skipped and reported. Cleanup removes exact copies, keeps the folder structure, and never removes folders with contents.</div><div class="batch-stats"><span>${num(job.processed)} / ${num(job.total)} checked</span><span>${num(job.groups)} exact-match groups</span><span>${num(job.remove_count)} proposed copies</span><span>${bytes(job.bytes)} logical</span><span>${num(job.recycled)} recycled</span><span>${num(job.warnings)} warnings</span></div>${job.error?`<p class="error">${esc(job.error)}</p>`:''}${review.map(g=>`<section class="batch-group"><p><strong>✓ KEEP</strong> · ${esc(g.keep.drive_name)} · ${date(g.keep.mtime)}</p><p class="cleanup-path keep">${esc(g.keep.path)}</p>${g.discard.map(e=>`<p class="cleanup-path discard">${e.action_status==='recycled'?"✓ Recycled":"→ Recycle"} · ${esc(e.path)} · ${bytes(e.size)}</p>`).join('')}<small>SHA-256 ${esc(g.sha256)}</small></section>`).join('')}${job.groups?`<div class="pagination"><span>Groups ${Math.min(pageOffset+1,job.groups)}–${Math.min(pageOffset+10,job.groups)} of ${num(job.groups)}</span><div class="actions"><button data-batch-prev ${pageOffset?'':'disabled'}>← Previous</button><button data-batch-next ${pageOffset+10<job.groups?'':'disabled'}>Next →</button></div></div>`:''}${job.errors.length?`<details><summary>Warnings and skipped files (up to 100)</summary>${job.errors.map(e=>`<p class="cleanup-path">${esc(e.message)}</p>`).join('')}</details>`:''}${ready?`<div class="notice">This plan expires after 30 minutes. Each group and its keeper are reverified before any move. The catalog is backed up. Projects using removed paths may need relinking. Restore originals from the Recycle Bin; the SQLite backup restores metadata only. Space is not freed until the Recycle Bin is emptied.</div><label class="check"><input type="checkbox" data-batch-confirm ${reviewConfirmed?'checked':''}> I have reviewed the scope and want to move the ${num(job.remove_count)} proposed copies to the Recycle Bin.</label><button class="danger" data-batch-execute ${reviewConfirmed&&job.groups?'':'disabled'}>Confirm cleanup ${job.scope_id?"in this project":'global'}</button>`:''}${busy||ready?"<button data-batch-stop>Stop / cancel plan</button>":''}${!busy&&!ready?"<p class=\"notice\">Files can be restored from the Windows Recycle Bin. No permanent deletion is used.</p>":''}${job.backup?`<p><small>Backup: ${esc(JSON.parse(job.backup).path)}</small></p>`:''}`;const body=dialog.querySelector('[data-batch-body]');body.querySelector('[data-batch-prev]')?.addEventListener('click',()=>{pageOffset=Math.max(0,pageOffset-10);void poll()});body.querySelector('[data-batch-next]')?.addEventListener('click',()=>{pageOffset+=10;void poll()});body.querySelector('[data-batch-confirm]')?.addEventListener('change',event=>{reviewConfirmed=event.target.checked;body.querySelector('[data-batch-execute]').disabled=!reviewConfirmed||!job.groups});body.querySelector('[data-batch-execute]')?.addEventListener('click',()=>act(async()=>{if(!reviewConfirmed)return;body.querySelector('[data-batch-execute]').disabled=true;await api('cleanup-batches/'+id+'/confirm','POST',{confirm:true});reviewConfirmed=false;await poll()}));body.querySelector('[data-batch-stop]')?.addEventListener('click',()=>act(async()=>{await api('cleanup-batches/'+id+'/cancel','POST');await poll()}));if(!busy){clearInterval(pollTimer);pollTimer=undefined}else if(!pollTimer)pollTimer=setInterval(()=>void poll(),1800)}catch(error){toast(error.message);clearInterval(pollTimer)}finally{polling=false}};await poll()}

let overviewDrive='',overviewRequest=0;
async function renderOverview(){
 if(overviewDrive&&!drives.some(d=>d.id===overviewDrive))overviewDrive='';
 const version=++overviewRequest,scope=overviewDrive;
 $('#content').innerHTML=`<div class="overview-layout"><section class="overview-sources" aria-label="Drive selection"><div class="section-head"><h2>Your drives <span class="badge">${drives.length}</span></h2><button data-page-link="Drives">Manage →</button></div><div class="overview-drive-list"><button class="overview-source overview-global ${scope?'':'selected'}" data-overview-drive="" aria-pressed="${!scope}"><span class="overview-source-icon">◈</span><span class="overview-source-main"><strong>Global archive</strong><span>Everything cataloged · ${num(drives.length)} drives / roots</span><small>${num(drives.reduce((sum,d)=>sum+d.files,0))} files · ${bytes(drives.reduce((sum,d)=>sum+d.bytes,0))} logical</small></span><span class="overview-choice">${scope?'':'✓'}</span></button>${drives.map(d=>`<button class="overview-source ${scope===d.id?'selected':''}" data-overview-drive="${esc(d.id)}" aria-pressed="${scope===d.id}">${diskIcon()}<span class="overview-source-main"><strong>${esc(d.name)}</strong><span>${esc(d.label||"Unlabeled")} · <span class="${d.connected?'overview-online':''}">${d.connected?"Connected":'Offline'}</span></span><small class="overview-source-path">${esc(d.current_root||d.root)}</small><small>${num(d.files)} files · ${bytes(d.bytes)} logical</small>${technicalDrive(d)}<small>Last scan · ${esc(date(d.last_scan))}</small></span><span class="overview-choice">${scope===d.id?'✓':''}</span></button>`).join('')}</div>${drives.length?'':"<p>Add a drive to start your catalog.</p><button class=\"primary\" data-add>+ Add drive</button>"}<p class="notice">Global combines registered catalogs, including offline drives. Overlapping roots may count the same content more than once.</p></section><section class="overview-details" aria-label="Selection summary" aria-live="polite" aria-busy="true"><p class="muted">Updating summary…</p></section></div>`;
 const details=$('.overview-details');
 try{
  const a=await api('overview'+(scope?'?drive_id='+encodeURIComponent(scope):''));
  if(version!==overviewRequest||page!=='Overview'||!details.isConnected)return;
  const t=a.totals,d=drives.find(d=>d.id===scope),selectedDrives=d?[d]:drives;
  details.innerHTML=`<div class="section-head"><h2>Overview · ${esc(d?d.name:'Global')}</h2><span class="badge ${d?.connected?'online':''}">${d?(d.connected?"Connected":"Offline catalog"):"All drives"}</span></div><div class="overview-update actions"><button class="primary" data-update-scope="${esc(scope)}" ${selectedDrives.some(x=>x.connected)?'':'disabled'}>${d?(d.last_scan?'↻ Update':'▸ Scan'):'↻ Update Global'}</button><button data-update-history="${esc(scope)}">Update history</button></div><p class="overview-updated muted">${d?"Last update · "+esc(date(d.last_scan)):"Global brings together the latest saved catalog from each drive."}</p>${d?technicalDrive(d):"<p class=\"global-description\">A combined catalog view. Logical sizes include indexed copies; Global is not a physical drive.</p>"}<div class="stats overview-stats"><div class="stat"><span class="muted">Indexed files</span><strong>${num(t.files)}</strong><small>Available in the offline catalog</small></div><div class="stat"><span class="muted">Logical size</span><strong>${bytes(t.bytes)}</strong><small>Sum of file sizes</small></div><div class="stat"><span class="muted">${d?"Selected root":"Registered roots"}</span><strong>${num(selectedDrives.length)}</strong><small>${num(selectedDrives.filter(x=>x.connected).length)} conectadas</small></div><div class="stat"><span class="muted">Cataloged folders</span><strong>${num(t.folders)}</strong><small>Original hierarchy preserved</small></div></div><div class="section-head"><h2>Archive composition</h2><span class="muted">${esc(d?d.name:'Global')}</span></div><div class="panel overview-composition">${distribution(a.categories)}</div><p class="notice">Composition by logical file size. Your selection applies to the summary and every category.</p>`;
 }catch(e){if(version===overviewRequest&&details.isConnected)details.innerHTML=`<p class="error">${esc(e.message)}</p><button data-overview-drive="${esc(scope)}">Retry</button>`;throw e}
 finally{if(details.isConnected)details.setAttribute('aria-busy','false')}
}
$('#content').addEventListener('click',e=>{const b=e.target.closest('[data-overview-drive]');if(!b)return;overviewDrive=b.dataset.overviewDrive;act(renderOverview)});

let updatesDrive='',updatesOffset=0;
const changeLabel=k=>({added:'Agregados',modified:"Modified",missing:"Missing",restored:'Reaparecidos'}[k]||k);
async function renderUpdates(){
 const r=await api('updates?'+new URLSearchParams({drive_id:updatesDrive,offset:updatesOffset}));if(page!=='Updates')return;
 $('#page-actions').innerHTML="<button id=\"updates-refresh\">↻ Refresh</button>";
 $('#updates-refresh').onclick=()=>act(renderUpdates);
 $('#content').innerHTML=`<p class="notice">History, dates, and change comparisons work locally without AI. A missing entry means its path was not found during a complete scan; it does not mean Disk Atlas deleted the file. Scans with warnings keep earlier records when absence cannot be confirmed.</p><div class="updates-policies">${r.policies.map(p=>`<section class="panel"><h2>${esc(p.name)}</h2><p>Last published update: <strong>${esc(date(p.last_scan))}</strong></p><p>Last status: ${esc(p.latest_status||"Not scanned")}</p><form data-policy="${esc(p.id)}"><label class="check"><input type="checkbox" name="enabled" ${p.enabled?'checked':''}> Update automatically when connected</label><label>Interval in hours<input type="number" name="hours" min="1" max="720" value="${p.interval_hours}" required></label><button type="submit">Save schedule</button></form>${p.last_attempt?`<p>Last automatic attempt: ${esc(date(p.last_attempt))}</p>`:''}${p.last_error?`<p class="error">${esc(p.last_error)}</p>`:''}</section>`).join('')}</div><p class="notice">The scheduler checks once a minute. Disk Atlas must be running and the drive connected. Paused scans are respected and settings survive a restart. No Windows service is installed.</p><div class="section-head"><h2>Permanent history</h2><select id="updates-drive"><option value="">All drives</option>${drives.map(d=>`<option value="${esc(d.id)}" ${updatesDrive===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></div>${r.history.items.map(s=>`<article class="scan"><div class="section-head"><h3>${esc(s.drive_name)}</h3><span class="badge">${esc(s.status)}</span></div><p>Start: ${esc(date(s.started))}<br>Finished: ${s.finished?esc(date(s.finished)):['cancelled','completed','completed_with_warnings'].includes(s.status)?"Date not recorded by this earlier version":'Pendiente'} · ${s.origin==='scheduled'?'Programado':"Manual / earlier"}</p><div class="scan-stats">${['added','modified','missing','restored'].map(k=>`<span>${num(s.changes[k]||0)} ${changeLabel(k)}</span>`).join('')}<span>${num(s.warnings)} warnings</span></div>${s.hidden?"<small>Hidden from Recent Scans; history kept.</small>":''}${s.error?`<p class="error">${esc(s.error)}</p>`:''}<div class="actions"><button data-changes="${esc(s.id)}">View changes and warnings</button></div></article>`).join('')||empty("No updates recorded","Use Scan or Update to save the first catalog version.")}<div class="pagination"><span>${num(r.history.total)} actualizaciones</span><div class="actions"><button id="updates-prev" ${updatesOffset?'':'disabled'}>← Previous</button><button id="updates-next" ${updatesOffset+20<r.history.total?'':'disabled'}>Next →</button></div></div>`;
 $('#updates-drive').onchange=e=>{updatesDrive=e.target.value;updatesOffset=0;act(renderUpdates)};$('#updates-prev').onclick=()=>{updatesOffset=Math.max(0,updatesOffset-20);act(renderUpdates)};$('#updates-next').onclick=()=>{updatesOffset+=20;act(renderUpdates)};
 document.querySelectorAll('[data-policy]').forEach(form=>form.onsubmit=e=>{e.preventDefault();act(async()=>{await api('drives/'+form.dataset.policy+'/update-policy','POST',{enabled:form.elements.enabled.checked,interval_hours:Number(form.elements.hours.value)});toast("Local schedule saved");await renderUpdates()})});
}
async function showScanChanges(sid){
 const dialog=document.createElement('dialog');dialog.className='cleanup-dialog';dialog.innerHTML="<div class=\"modal-heading\"><h2>Update changes</h2><button data-close>×</button></div><div data-history>Loading…</div>";document.body.append(dialog);dialog.showModal();let offset=0,kind='',version=0;
 const close=()=>{dialog.close();dialog.remove()};dialog.querySelector('[data-close]').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close()});
 const load=async()=>{const request=++version,r=await api('scans/'+sid+'/changes?'+new URLSearchParams({offset,limit:100,kind}));if(!dialog.isConnected||request!==version)return;const body=dialog.querySelector('[data-history]');body.innerHTML=`<p><strong>${esc(r.scan.drive_name)}</strong> · ${esc(r.scan.status)}<br>Start: ${esc(date(r.scan.started))}<br>Finished: ${r.scan.finished?esc(date(r.scan.finished)):['cancelled','completed','completed_with_warnings'].includes(r.scan.status)?"Date not recorded by this earlier version":'Pendiente'}</p><div class="scan-stats">${Object.entries(r.counts).map(([k,n])=>`<span>${num(n)} ${changeLabel(k)}</span>`).join('')}<span>${num(r.warning_total)} warnings</span></div><label>Change type<select data-kind><option value="">All</option>${['added','modified','missing','restored'].map(k=>`<option value="${k}" ${kind===k?'selected':''}>${changeLabel(k)}</option>`).join('')}</select></label><div class="history-events">${r.changes.map(e=>`<div><span class="badge">${changeLabel(e.kind)}</span><span class="cleanup-path">${esc(e.rel)}</span></div>`).join('')||"<p>No changes recorded on this page.</p>"}${r.warnings.map(e=>`<p class="cleanup-path error">Warning · ${esc(e.path)} · ${esc(e.message)}</p>`).join('')}</div><div class="pagination"><span>${num(r.total)} changes · ${num(r.warning_total)} warnings</span><div class="actions"><button data-prev ${offset?'':'disabled'}>← Previous</button><button data-next ${offset+100<Math.max(r.total,r.warning_total)?'':'disabled'}>Next →</button></div></div><p class="notice">Changes describe the catalog published when that scan finished. Paused or canceled scans keep the last published version. This log records catalog changes, not earlier versions of file contents.</p>`;body.querySelector('[data-kind]').onchange=e=>{kind=e.target.value;offset=0;act(load)};body.querySelector('[data-prev]').onclick=()=>{offset=Math.max(0,offset-100);act(load)};body.querySelector('[data-next]').onclick=()=>{offset+=100;act(load)}};await load();
}
$('#content').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-update-history')){updatesDrive=b.dataset.updateHistory;updatesOffset=0;act(()=>navigate('Updates'))}if(b.hasAttribute('data-update-scope'))act(async()=>{b.disabled=true;try{const r=await api('updates/run','POST',{drive_id:b.dataset.updateScope});toast(r.started.length+" updates started"+(r.skipped.length?' · '+r.skipped.length+" drives skipped":''));if(r.started.length)await navigate('Recent Scans')}finally{if(b.isConnected)b.disabled=false}})});

$('#content').addEventListener('click',event=>{const b=event.target.closest('[data-json-anchor]');if(!b)return;act(async()=>{const original=b.textContent;b.disabled=true;b.textContent="Preparing JSON…";try{let s=await api('drives/'+b.dataset.jsonAnchor+'/json-snapshot');if(!s.available||!s.current||s.error)s=await api('drives/'+b.dataset.jsonAnchor+'/json-snapshot','POST');const dialog=document.createElement('dialog');dialog.innerHTML=`<div class="modal-heading"><h2>Catalog JSON</h2><button data-close>×</button></div><p>Last generated: ${esc(date(s.generated))}<br>${num(s.entry_count)} files and folders · ${bytes(s.bytes)}</p><p>A local snapshot of the last published catalog, including its drive, paths, metadata, and saved notes. Offline search uses SQLite.</p><a class="download" href="/api/download/manifests/${encodeURIComponent(s.name)}">Download JSON ↓</a><button data-refresh-json>Regenerate with current metadata</button>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.querySelector('[data-refresh-json]').onclick=()=>act(async()=>{await api('drives/'+b.dataset.jsonAnchor+'/json-snapshot','POST');dialog.close();toast("JSON updated");b.click()})}finally{b.disabled=false;b.textContent=original}})});

async function editDriveModal(id){
 const d=drives.find(x=>x.id===id);if(!d)return;
 const dialog=document.createElement('dialog');dialog.className='lightbox drive-edit-dialog';dialog.setAttribute('aria-labelledby','drive-edit-title');dialog.innerHTML=`<form><div class="modal-heading"><div><small>CATALOG SETTINGS</small><h2 id="drive-edit-title">Edit drive</h2></div><button type="button" data-close aria-label="Close editor">×</button></div><p class="cleanup-path">${esc(d.root)}</p><div class="two"><label>Name<input name="name" value="${esc(d.name)}" required maxlength="200"></label><label>Physical label<input name="label" value="${esc(d.label||'')}" maxlength="200"></label></div><label>Description<textarea name="description" rows="3">${esc(d.description||'')}</textarea></label><label>Tags<input name="tags" value="${esc(d.tags||'')}"></label><p class="notice">These details are saved in the local catalog. The drive's name and files are not changed.</p><p data-error class="error" role="status"></p><div class="modal-footer"><button type="button" data-close>Cancel</button><button class="primary" type="submit">Save changes</button></div></form>`;document.body.append(dialog);dialog.showModal();dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=dialog.querySelector('[type=submit]');button.disabled=true;button.textContent="Saving…";try{await api('drives/'+id,'PATCH',Object.fromEntries(new FormData(event.target)));dialog.close();toast("Drive updated");await render()}catch(error){dialog.querySelector('[data-error]').textContent=error.message;button.disabled=false;button.textContent="Save changes"}};
}
document.addEventListener('click',event=>{const dialog=event.target;if(!(dialog instanceof HTMLDialogElement)||!dialog.classList.contains('lightbox'))return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()});

function searchResultSummary(data,ms){const s=data.summary||{};return `<div class="explorer-summary"><strong>${num(data.total)} elementos</strong><span>${bytes(s.bytes)}</span><span>${data.by_drive?.length||0} discos</span><div class="format-chips">${(s.formats||[]).slice(0,6).map(f=>/^[a-z0-9_-]+$/i.test(f.ext)?`<button data-format-search="${esc(f.ext)}" title="Buscar *.${esc(f.ext)} across all drives">${esc(f.ext.toUpperCase())} <small>${num(f.count)}</small></button>`:'').join('')}</div><small>${(ms/1000).toFixed(2)} s · ${num(s.offline)} offline</small></div>`}


document.addEventListener('click',event=>{if(!event.target.closest('[data-io-policy]'))return;act(async()=>{const r=await api('io-budget'),dialog=document.createElement('dialog');dialog.className='lightbox';dialog.innerHTML=`<div class="modal-heading"><h2>Disk read limits</h2><button data-close>×</button></div><p>${num(r.cpu_threads)} CPU threads · ${bytes(r.ram_bytes)} RAM detected</p><p><strong>${r.global_limit} simultaneous heavy reads</strong> at most across the app.</p><p class="notice">${esc(r.policy)}</p>${r.devices.map(d=>`<section class="io-device"><strong>${esc(d.bus_type)}</strong><p>${d.active} active · ${d.queued} queued · limit ${d.limit}</p></section>`).join('')||"<p>No original-file reads requested yet.</p>"}<p class="notice">Scanning, hashing, and thumbnail generation share these limits. Catalog queries and saved thumbnails do not read originals. This limits concurrency; it is not a speed measurement in MB/s.</p>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});});});

async function openOriginal(id,connected=true){if(!connected)return toast("Connect the drive to open the original. The catalog is still available offline.");await api('entries/'+id+'/open','POST',{mode:'open'})}
function diskIcon(){return '<svg class="disk-line-icon" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><rect x="5" y="4" width="22" height="24" rx="3"/><circle cx="16" cy="14" r="6"/><circle cx="16" cy="14" r="1.6"/><path d="m20 18 3 3M8 24h3m2 0h3m7-17v2"/></svg>'}
function technicalDrive(d){const t=d.technical;if(!t?.capacity)return "<p class=\"drive-technical muted\">Capacity details are available when the drive is connected.</p>";const used=Math.max(0,t.capacity-(t.free||0)),percent=Math.min(100,used/t.capacity*100);return `<div class="drive-technical"><div><strong>${bytes(t.free)} free</strong><span>of ${bytes(t.capacity)}</span></div><div class="capacity-track"><i style="width:${percent}%"></i></div><small>${esc(t.filesystem||"Unknown format")} · ${esc(t.bus_type||"Unknown connection")} ${t.hardware?' · '+esc(t.hardware):''}</small>${!d.connected?`<small>Last read: ${esc(date(t.observed))}</small>`:''}</div>`}
document.addEventListener('click',event=>{const b=event.target.closest('[data-format-search]');if(!b)return;act(async()=>{if(page!=='All Files')await navigate('All Files');$('#search').value='*.'+b.dataset.formatSearch;for(const id of ['drive-filter','category-filter','tag-filter','project-filter','min-size','after-filter','before-filter'])if($('#'+id))$('#'+id).value='';rootDrive='';folder='';offset=0;await loadFiles()})});
const workItems=new Map();let workSequence=0,activityBusy=false,backgroundActivity='',lastHardwareAt=0,lastScanSignature='';
function beginWork(label){const id=++workSequence;workItems.set(id,{label,start:Date.now()});updateWorkStatus();return()=>{workItems.delete(id);updateWorkStatus()}}
function workLabel(path,method){if(/^(activity|session|drives$|scans$|io-budget)/.test(path))return '';if(path.includes('thumbnail'))return "Generating thumbnails in the background…";if(path.includes('/open'))return "Opening the file in its app…";if(method!=='GET')return "Saving and checking the operation…";return "Preparing catalog data…"}
function updateWorkStatus(){const box=$('#work-status');if(!box)return;const first=workItems.values().next().value;box.hidden=!first&&!backgroundActivity;box.classList.toggle('is-working',!!first||!!backgroundActivity);box.innerHTML=(first||backgroundActivity)?'<span class="loading-orbit"></span><span>'+esc(first?(Date.now()-first.start>1800?"Still working… "+first.label:first.label):backgroundActivity)+'</span>':'';document.body.classList.toggle('app-working',!!first||!!backgroundActivity)}
async function pollActivity(){if(activityBusy||document.hidden)return;activityBusy=true;try{const r=await api('activity'),active=r.scans||[],queued=r.io.devices.reduce((n,d)=>n+d.queued,0);backgroundActivity=active.length?'Actualizando '+active.map(s=>s.name+' · '+num(s.files)+" files").join(' / '):r.batches.length?"Checking duplicates in the background…":queued?queued+" reads waiting for a slot…":r.hardware_refreshing?"Detecting drives in the background…":'';const scanSignature=active.map(s=>s.id).join(',');const scanTransition=lastScanSignature!==scanSignature&&!!lastScanSignature;lastScanSignature=scanSignature;if(r.hardware_at!==lastHardwareAt||scanTransition){lastHardwareAt=r.hardware_at;await refreshDrives(true);if(page==='Overview')await renderOverview();else if(page==='Drives')$('#content').innerHTML='<div class="drive-grid">'+drives.map(driveCard).join('')+'</div>';else if(page==='All Files'&&$('#results')&&explorerAtComputer())rootLocations();else if($('#results')){for(const item of items){item.connected=!!drives.find(d=>d.id===item.drive_id)?.connected;const row=document.querySelector('#results tr[data-id="'+item.id+'"]');if(row){const badge=row.lastElementChild?.querySelector('.badge');if(badge){badge.textContent=item.connected?'● Connected':'○ Offline';badge.classList.toggle('online',item.connected)}}}}}if(page==='Recent Scans'&&!document.querySelector('dialog[open]'))await renderScans();updateWorkStatus()}catch{}finally{activityBusy=false}}
setInterval(updateWorkStatus,1000);
